+
+    /// Every family carries Python's name, type, help, label names and default
+    /// buckets; every other family Python registers is listed as not recorded.
+    #[test]
+    fn families_match_python() {
+        let fixture = fixture();
+        let metrics = FrontendMetrics::new(
